/// Returns a new `Vec<u8>` containing `count` bytes copied from `buffer`
/// starting at index `offset`.
///
/// Assumptions (as stated in the problem):
/// - `offset` and `count` are non-negative (true for `usize`)
/// - `offset + count <= buffer.len()`
/// - `count == 0` OR `offset < buffer.len()`
pub fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Slice is `[start, end)` so end is `offset + count`.
    buffer[offset..offset + count].to_vec()
}